import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SingularValueDecompositionImpl.getU()
 */
public class SingularValueDecompositionImpl_getU_TriageGen1Test {







    /**
     * Test Case 4: Test with a singular matrix (Rank deficient).
     * Ensures the algorithm handles zero or near-zero singular values if possible,
     * though SVD implementation typically handles this via epsilon.
     */
    @Test
    public void testGetU_SingularMatrix() throws InvalidMatrixException {
        // Rank 1 matrix
        double[][] data = {
            {1.0, 1.0},
            {1.0, 1.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u = svd.getU();
        RealMatrix s = svd.getS();
        RealMatrix vt = svd.getVT();
        RealMatrix reconstructed = u.multiply(s).multiply(vt);

        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                Assert.assertEquals(data[i][j], reconstructed.getEntry(i, j), 1e-9);
            }
        }
    }
}
